    "text": "    def find_by_age_range(self, min_age: int, max_age: int) -> list[User]:\n        \"\"\"\n        年齢範囲でユーザーを検索する\n\n        Args:\n            min_age: 最小年齢（含む）\n            max_age: 最大年齢（含む）\n\n        Returns:\n            条件に一致するユーザーのリスト\n        \"\"\"\n        result = []\n        for user in self._users.values():\n            if min_age <= user.age <= max_age:\n                result.append(user)\n        return result\n\n    def find_by_email_domain(self, domain: str) -> list[User]:\n        \"\"\"\n        メールドメインでユーザーを検索する\n\n        Args:\n            domain: メールドメイン（例: \"example.com\"）\n\n        Returns:\n            条件に一致するユーザーのリスト\n        \"\"\"\n        result = []\n        domain_suffix = f\"@{domain}\"\n        for user in self._users.values():\n            if user.email.endswith(domain_suffix):\n                result.append(user)\n        return result\n\n    def get_user_count(self) -> int:\n        \"\"\"\n        登録ユーザー数を取得する\n\n        Returns:\n            登録ユーザー数\n        \"\"\"\n        return len(self._users)\n\n    # --- バリデーションメソッド ---\n\n"
